def page(title,description,url,body,schema=None):
 esc=html.escape
 if schema is not None:
  schema=dict(schema)
  schema['@id']='https://sidecourt.space'+url+'#entity'
  if url.startswith('/skills/') and url!='/skills/':
   schema={'@context':'https://schema.org','@graph':[schema,{'@type':'BreadcrumbList','itemListElement':[{'@type':'ListItem','position':1,'name':'Skills','item':'https://sidecourt.space/skills/'},{'@type':'ListItem','position':2,'name':title,'item':'https://sidecourt.space'+url}]}]}
 structured='' if schema is None else '<script type="application/ld+json">'+json.dumps(schema).replace('</','<\\/')+'</script>'
 links=''.join('<a href="'+u+'"'+(' aria-current="page"' if u=='/skills/' and url.startswith('/skills/') else '')+'>'+label+'</a>' for u,label in [('/', 'HOME'),('/discovery/', 'DISCOVERY'),('/skills/', 'SKILLS'),('/season', 'SEASON'),('/get-on', 'GET ON THE COURT'),('/your-court', 'YOUR COURT')])
 navigation='<header class="catalog-header"><a class="catalog-brand" href="/" aria-label="SideCourt home"><img src="/assets/logo-cream.svg" alt="SideCourt"></a><nav class="catalog-nav" aria-label="Main navigation">'+links+'</nav><details class="catalog-mobile-nav"><summary>Menu</summary><nav aria-label="Mobile navigation">'+links+'</nav></details></header>'
 if url.startswith('/skills/') and url!='/skills/':body='<article class="catalog-detail">'+body+'</article>'
 document='<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'+esc(title)+' · SideCourt</title><meta name="description" content="'+esc(description,quote=True)+'"><link rel="canonical" href="https://sidecourt.space'+url+'"><meta property="og:title" content="'+esc(title,quote=True)+'"><meta property="og:description" content="'+esc(description,quote=True)+'"><meta property="og:url" content="https://sidecourt.space'+url+'"><link rel="icon" href="/favicon.svg"><link rel="preload" href="/assets/InterLatin.woff2" as="font" type="font/woff2" crossorigin><style>'+STYLE+'</style>'+structured+'</head><body class="catalog-page">'+navigation+'<main>'+body+'<footer>Made by Ming (<a href="/people/m1nga/">@m1nga</a>) · <a href="/">SideCourt</a> · <a href="/tools/">All products and skills</a></footer></main></body></html>'
 return search_metadata(document,title+' · SideCourt',description,'https://sidecourt.space'+url)

def card(x):
 e=html.escape
 art={'redbot':'/drops/redbot/app/icon.svg','daycup':'/drops/daycup/app/icon-512.png','cleanpause':'/origin-assets/layout-assets/cleanpause-icon.png'}
 preview=x.get('preview_image','')
 if re.fullmatch(r'/tools/previews/[a-z0-9_-]+\.(?:jpg|png|webp)',preview):media='<img class="catalog-preview" src="'+e(preview,quote=True)+'" alt="'+e(x['name']+' homepage',quote=True)+'" loading="lazy">'
 elif x['slug'] in art:media='<img src="'+art[x['slug']]+'" alt="" loading="lazy">'
 else:media='<span class="catalog-name-cover">'+e(x['name'])+'</span>'
 return '<a class="card '+('legacy' if x['status']=='Legacy' else '')+'" href="'+x['url']+'" data-entry="'+e((x['name']+' '+x['description']+' '+x['kind']).lower(),quote=True)+'"><div class="catalog-cover">'+media+'</div><div class="catalog-copy"><small>'+e(x['kind'])+' · '+e(x['status'])+'</small><h2>'+e(x['name'])+'</h2><p>'+e(x['description'])+'</p><span>'+('See how to use it' if 'install' in x else 'Open the product')+' ↗</span></div></a>'


def skill_row(x):
 e=html.escape
 search=' '.join(str(x.get(key,'')) for key in ('name','description','kind','bring','status','category')).lower()
 category=x.get('category','')
 category_label='<span class="skill-category-label">'+e(category)+'</span>' if category else ''
 status='<small>Legacy · Reference</small>' if x['status']=='Legacy' else ('<small>'+e(x['status'])+'</small>' if x['status']!='Available' else '')
 bring='<p class="skill-bring">Bring: '+e(x['bring'])+'</p>' if x.get('bring') else ''
 return '<li data-entry="'+e(search,quote=True)+'" data-category="'+e(category,quote=True)+'"><a class="skill-row" href="'+e(x['url'],quote=True)+'"><img class="skill-ring" src="/assets/sidecourt-ring-cream.svg" alt="" width="36" height="36" loading="lazy"><div class="skill-name"><h2>'+e(x['name'])+'</h2>'+category_label+status+'</div><div class="skill-summary"><p>'+e(x['description'])+'</p>'+bring+'</div><span class="skill-entry">Guide <span aria-hidden="true">→</span></span></a></li>'


def inject_home_tools(document):
 if 'id="home-ming-tools"' in document:return document
 body='''<section class="section sc-owned-tools" id="home-ming-tools" aria-labelledby="ming-tools-title"><p class="eyebrow">MADE BY <a href="/people/m1nga/">@m1nga</a> · ON SIDECOURT</p><h2 id="ming-tools-title">Small tools. Useful work.</h2><p>Find a saved note, brew a coffee, or make your next project easier.</p><div class="sc-owned-cards"><a href="/drops/redbot/">RedBot<span>Find the useful thing you saved.</span></a><a href="/drops/daycup/">DayCup<span>A starting recipe and a place for your brew notes.</span></a><a href="/cleanpause/">CleanPause<span>A little pause while you clean your device.</span></a></div><a class="text-link" href="/products/">Explore products ↗</a><a class="text-link" href="/skills/">Find an AI skill ↗</a></section>'''
 marker='<section class="section" id="home-season">'
 if marker not in document:raise ValueError('Expected home section boundary missing; do not silently overwrite the homepage.')
 document=document.replace(marker,body+marker,1)
 prefix,tail=document.split('<main id="main-home"',1)
 prefix=prefix.replace('<a href="/discovery/">DROPS</a>','<a href="/discovery/">DISCOVERY</a>').replace('<a href="/discovery/">DISCOVERY</a>','<a href="/discovery/">DISCOVERY</a><a href="/skills/">SKILLS</a>')
 document=prefix+'<main id="main-home"'+tail
 css='<style>.sc-owned-tools{padding-block:40px}.sc-owned-tools h2{font-size:clamp(32px,4vw,56px);margin:14px 0}.sc-owned-cards{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:16px;margin:24px 0}.sc-owned-cards a{display:block;padding:22px;border:1px solid currentColor;border-radius:10px;color:inherit;text-decoration:none;font-size:24px}.sc-owned-cards span{display:block;font:14px/1.5 system-ui;margin-top:10px;opacity:.8}@media(max-width:650px){.sc-owned-cards{grid-template-columns:1fr}}</style>'
 return document.replace('</head>',css+'</head>',1)

def publish_tools(root,out):
 data=json.loads((root/'tools/catalog.json').read_text());items=data['items'];e=html.escape
 shutil.copytree(root/'tools',out/'tools',dirs_exist_ok=True)
 urls=[]
 for kind,url,title,heading,description in [
  ('all','/tools/','Independent Apps and AI Agent Skills','Something useful,<br>within reach.','Apps to open and skills to use with your AI. All made by Ming.'),
  ('products','/products/','Coffee, Audio, Saved Research and Mac Cleaning Apps','Less friction.<br>More doing.','Open a web app or download a product. Pick the thing you want help with.'),
  ('skills','/skills/','AI Agent Skills for Codex and Compatible Assistants','Skills','Skills are reusable instructions and tools for your AI assistant. Choose a task, open the guide, then install.')]:
  selected=items if kind=='all' else [x for x in items if ('install' in x if kind=='skills' else x['kind']!='Skill')]
  if kind=='skills':selected=[dict(x,url='/skills/'+x['slug']+'/') for x in selected]
  intro='<h1>'+heading+'</h1><p class="catalog-intro">'+e(description)+'</p><label for="tool-search">What would you like help with?</label><input id="tool-search" type="search" placeholder="Try saved links, coffee, handoff or design"><small id="count" role="status">'+str(len(selected))+' '+('skills' if kind=='skills' else 'products' if kind=='products' else 'products and skills')+'</small>'
  if kind=='skills':
   intro+='<nav class="skill-categories" aria-label="Filter skills by category">'+''.join('<button type="button" data-skill-category="'+e(category,quote=True)+'" aria-pressed="'+str(category=='All').lower()+'">'+e(category)+' <span>'+str(len(selected) if category=='All' else sum(x.get('category')==category for x in selected))+'</span></button>' for category in ('All',)+SKILL_CATEGORIES)+'</nav>'
   intro+='<p class="catalog-note">Each guide includes an install command, examples and the exact instructions. Legacy skills remain available as references.</p>'
  intro+='<button type="button" id="tool-reset" hidden>Clear filters</button>'
  schema={'@context':'https://schema.org','@type':'ItemList','name':title+' by Ming on SideCourt','itemListElement':[{'@type':'ListItem','position':i+1,'name':x['name'],'url':'https://sidecourt.space'+x['url']} for i,x in enumerate(selected)]}
  search='''<script>const search=document.querySelector('#tool-search'),buttons=[...document.querySelectorAll('[data-skill-category]')],reset=document.querySelector('#tool-reset'),params=new URLSearchParams(location.search);let category=buttons.some(b=>b.dataset.skillCategory===params.get('category'))?params.get('category'):'All';search.value=params.get('q')||'';const apply=(write=false)=>{const q=search.value.toLowerCase().trim();let n=0;for(const row of document.querySelectorAll('[data-entry]')){row.hidden=!row.dataset.entry.includes(q)||(category!=='All'&&row.dataset.category!==category);if(!row.hidden)n++;}buttons.forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.skillCategory===category)));document.querySelector('#count').textContent=n?`${n} results${category==='All'?'':' in '+category}`:'No match. Try a different task or clear the search.';reset.hidden=!q&&category==='All';if(write){const url=new URL(location.href);q?url.searchParams.set('q',search.value.trim()):url.searchParams.delete('q');category==='All'?url.searchParams.delete('category'):url.searchParams.set('category',category);history.replaceState(null,'',url);}};search.oninput=()=>apply(true);buttons.forEach(b=>b.onclick=()=>{category=b.dataset.skillCategory;apply(true)});reset.onclick=()=>{search.value='';category='All';apply(true);search.focus()};apply();</script>'''
  folder=out/url.strip('/');folder.mkdir(parents=True,exist_ok=True)
  listing='<ul class="skill-list" aria-label="Skills">'+''.join(skill_row(x) for x in selected)+'</ul>' if kind=='skills' else '<div class="grid">'+''.join(card(x) for x in selected)+'</div>'
  (folder/'index.html').write_text(page(title,description,url,intro+listing+search,schema))
  urls.append('https://sidecourt.space'+url)
 for x in items:
  if 'install' not in x:continue
  slug=x['slug'];folder=out/'skills'/slug;folder.mkdir(parents=True,exist_ok=True)
  body='<p class="eyebrow">'+e(x['name'])+' · AI ASSISTANT SKILL · '+e(x['status'])+'</p><h1>'+e(x['description'])+'</h1><p><strong>Bring:</strong> '+e(x.get('bring','Your task and relevant source material.'))+'</p><p><strong>Get:</strong> '+e(x.get('result','A result within the skill’s documented scope.'))+'</p>'
  if x['status']=='Legacy':body+='<p>This legacy skill remains available for reference. It is not a current default workflow.</p>'
  if slug=='redbot':body+='<div class="actions"><a class="button" href="/drops/redbot/app/">Try RedBot</a><a class="button secondary" href="/drops/redbot/">Product & privacy</a><a class="button secondary" href="/drops/redbot/test/">User test</a></div>'
  if x.get('example'):body+='<h2>Try a real request.</h2><blockquote>'+e(x['example'])+'</blockquote>'
  body+='<h2>Use it with your AI assistant.</h2><p>Install the skill in a compatible assistant, then describe the task and give it access only to the material you want it to use. A skill is instructions and supporting tools; it is not a separate chat service or a model subscription.</p><pre id="install">'+e(x['install'])+'</pre><div class="actions"><button id="copy">Copy install command</button><a class="button secondary" href="'+x['package']+'" download>Download skill package</a></div><p id="copy-status" role="status"></p><h2>Read the exact instructions.</h2><p><a href="/tools/sources/'+slug+'/SKILL.md">Skill instructions</a> · <a href="/tools/sources/'+slug+'/README.md">Full guide and examples</a> · <a href="'+x['repository']+'" rel="noopener noreferrer">Source code on GitHub ↗</a></p><p>The package is sourced from the public registry at commit '+e(x.get('source_commit',data['source_commit'])[:12])+'. Product-specific permissions, dependencies and limits are in its guide. Installing does not grant permission to publish, send messages, spend money or access unrelated files.</p>'
  body+='<script>document.querySelector("#copy").onclick=async()=>{try{await navigator.clipboard.writeText(document.querySelector("#install").textContent);document.querySelector("#copy-status").textContent="Copied. Paste into your terminal to install.";}catch{document.querySelector("#copy-status").textContent="Copy the command above manually.";}};</script>'
  (folder/'index.html').write_text(page(x['title'],x['description'],'/skills/'+slug+'/',body,{'@context':'https://schema.org','@type':'SoftwareSourceCode','name':x['title'],'description':x['description'],'url':'https://sidecourt.space/skills/'+slug+'/','codeRepository':x['repository'],'author':{'@type':'Person','name':'Ming','url':'https://sidecourt.space/people/m1nga/'}}))
  urls.append('https://sidecourt.space/skills/'+slug+'/')
 shutil.copytree(root/'redbot',out/'drops/redbot',dirs_exist_ok=True)
 urls += ['https://sidecourt.space/drops/redbot/','https://sidecourt.space/drops/redbot/app/']
 # Familiar route aliases enter the same canonical platform page.
 for path,target in [('redbot','/drops/redbot/')]:
  folder=out/path;folder.mkdir(exist_ok=True);(folder/'index.html').write_text('<!doctype html><html lang="en"><meta charset="utf-8"><title>SideCourt</title><link rel="canonical" href="https://sidecourt.space'+target+'"><meta http-equiv="refresh" content="0;url='+target+'"><a href="'+target+'">Continue to SideCourt</a></html>')
 print('Published',len(items),'owned product entries and',sum('install' in x for x in items),'skill packages.')
 return urls
